/* CSS PART 2 OF 4 */

/* =========================================
   HEADER, NAVIGATION, HERO & PRIMARY ACTION
   Josh Brooks Construction & Renovation Inc.
   ========================================= */

/* 1. SITE HEADER */

.site-header {
  position: relative;
  z-index: 1000;
  width: 100%;
  background: var(--color-paper);
  border-bottom: 1px solid rgba(32, 42, 46, 0.12);
}

.header-inner {
  width: min(
    var(--container-wide),
    calc(100% - (var(--page-gutter) * 2))
  );
  min-height: 94px;
  margin-inline: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.9rem;
  min-width: 190px;
  color: var(--color-ink);
}

.site-brand img {
  width: 62px;
  height: 62px;
  object-fit: contain;
  flex-shrink: 0;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.035em;
}

.brand-descriptor {
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  line-height: 1.4;
  text-transform: uppercase;
}


/* 2. MAIN NAVIGATION */

.main-navigation {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(1rem, 2vw, 2rem);
}

.main-navigation ul {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 1.8vw, 1.75rem);
}

.main-navigation a {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--color-ink-soft);
  font-size: 0.82rem;
  font-weight: 650;
  transition: color var(--transition-fast);
}

.main-navigation a::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 2px;
  background: var(--color-accent);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition-fast);
}

.main-navigation a:hover,
.main-navigation a:focus-visible {
  color: var(--color-accent-dark);
}

.main-navigation a:hover::after,
.main-navigation a:focus-visible::after,
.main-navigation a[aria-current="page"]::after {
  transform: scaleX(1);
}


/* 3. HEADER CONTACT DETAILS */

.header-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.header-phone {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  white-space: nowrap;
}

.header-phone-label {
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.header-phone a {
  color: var(--color-ink);
  font-size: 0.92rem;
  font-weight: 750;
  transition: color var(--transition-fast);
}

.header-phone a:hover {
  color: var(--color-accent-dark);
}


/* 4. BUTTON SYSTEM */

.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding: 0.9rem 1.6rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.83rem;
  font-weight: 750;
  letter-spacing: 0.025em;
  line-height: 1.2;
  text-align: center;
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast),
    transform var(--transition-fast),
    box-shadow var(--transition-fast);
}

.button:hover {
  transform: translateY(-2px);
}

.button:active {
  transform: translateY(0);
}

.button-primary {
  background: var(--color-accent);
  color: var(--color-white);
  border-color: var(--color-accent);
}

.button-primary:hover {
  background: var(--color-accent-dark);
  border-color: var(--color-accent-dark);
  color: var(--color-white);
  box-shadow: var(--shadow-soft);
}

.button-dark {
  background: var(--color-ink);
  color: var(--color-white);
  border-color: var(--color-ink);
}

.button-dark:hover {
  background: var(--color-charcoal);
  border-color: var(--color-charcoal);
  color: var(--color-white);
}

.button-outline {
  background: transparent;
  color: var(--color-ink);
  border-color: rgba(32, 42, 46, 0.35);
}

.button-outline:hover {
  background: var(--color-ink);
  border-color: var(--color-ink);
  color: var(--color-white);
}

.button-light {
  background: var(--color-white);
  color: var(--color-ink);
  border-color: var(--color-white);
}

.button-light:hover {
  background: var(--color-stone);
  border-color: var(--color-stone);
}

.button-outline-light {
  background: transparent;
  color: var(--color-white);
  border-color: rgba(255, 255, 255, 0.65);
}

.button-outline-light:hover {
  background: var(--color-white);
  color: var(--color-ink);
}

.button-block {
  width: 100%;
}


/* 5. MOBILE NAVIGATION CONTROL */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-ink);
  cursor: pointer;
}

.menu-toggle span {
  display: block;
  width: 19px;
  height: 2px;
  background: currentColor;
  transition:
    transform var(--transition-fast),
    opacity var(--transition-fast);
}

.menu-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(7px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-7px) rotate(-45deg);
}


/* 6. HERO SECTION */

.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: min(760px, calc(100svh - 94px));
  padding-block: clamp(5rem, 9vw, 8.5rem);
  overflow: hidden;
  background: var(--color-charcoal);
  color: var(--color-white);
}

.hero-background {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-background img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 48%;
}

.hero-background::after {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(19, 29, 32, 0.94) 0%,
      rgba(19, 29, 32, 0.82) 43%,
      rgba(19, 29, 32, 0.34) 100%
    ),
    linear-gradient(
      0deg,
      rgba(19, 29, 32, 0.48),
      transparent 50%
    );
  content: "";
}

.hero-inner {
  position: relative;
  z-index: 1;
  width: min(
    var(--container),
    calc(100% - (var(--page-gutter) * 2))
  );
  margin-inline: auto;
}

.hero-content {
  max-width: 800px;
}

.hero .eyebrow {
  color: var(--color-accent-light);
}

.hero .eyebrow::before {
  background: var(--color-accent-light);
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 1.7rem;
  color: var(--color-white);
}

.hero h1 em {
  color: var(--color-accent-light);
  font-style: normal;
}

.hero-description {
  max-width: 590px;
  margin-bottom: 2rem;
  color: rgba(255, 255, 255, 0.82);
  font-size: clamp(1rem, 1.5vw, 1.2rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  margin-top: 2rem;
}

.hero .button-primary {
  min-height: 58px;
  padding-inline: 2rem;
}

.hero .button-outline-light {
  min-height: 58px;
  padding-inline: 2rem;
}


/* 7. HERO CREDENTIAL STRIP */

.hero-credentials {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 2rem;
  margin-top: 3.5rem;
  padding-top: 1.6rem;
  border-top: 1px solid rgba(255, 255, 255, 0.24);
}

.hero-credential {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  color: rgba(255, 255, 255, 0.88);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  line-height: 1.5;
  text-transform: uppercase;
}

.credential-mark {
  display: inline-flex;
  width: 27px;
  height: 27px;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--color-accent-light);
  border-radius: 50%;
  color: var(--color-accent-light);
  font-size: 0.75rem;
}


/* 8. HERO IMAGE DETAIL */

.hero-image-caption {
  position: absolute;
  right: var(--page-gutter);
  bottom: 2rem;
  z-index: 2;
  max-width: 260px;
  padding: 0.75rem 1rem;
  border-left: 2px solid var(--color-accent-light);
  background: rgba(23, 33, 37, 0.82);
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.7rem;
  line-height: 1.5;
}


/* 9. QUICK CONTACT BAR */

.quick-contact {
  position: relative;
  z-index: 2;
  background: var(--color-accent);
  color: var(--color-white);
}

.quick-contact-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  width: min(
    var(--container),
    calc(100% - (var(--page-gutter) * 2))
  );
  min-height: 76px;
  margin-inline: auto;
}

.quick-contact-copy {
  font-size: 0.9rem;
  font-weight: 650;
}

.quick-contact-links {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.quick-contact-links a {
  color: var(--color-white);
  font-size: 0.84rem;
  font-weight: 750;
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 4px;
